function extractGitHubLinks (content) {
  const regex = /\[([^\]]+)\]\((https:\/\/github\.com\/([^/]+)\/([^/)]+)[^)]*)\)/g
  const links = []
  let match

  while ((match = regex.exec(content)) !== null) {
    links.push({
      name: match[1],
      url: match[2],
      owner: match[3],
      repo: match[4].replace(/[#?].*$/, '')
    })
  }

  return links
}
